const prev = $('دریافت متن فارسی').first().json;
const res = $input.first().json;
const data = res.result ?? res.structuredContent ?? res;
const rules = data.rules ?? [];
const checklist = rules.map((r, i) => `${i + 1}. ${r.title}: ${r.rule}`).join('\n');
const prompt =
  `متن فارسی زیر را با این چک‌لیست ویراستاری کن. تک‌تک بندهای چک‌لیست را روی متن اعمال کن و فقط متن نهایی ویراسته را برگردان، بدون توضیح اضافه:\n\n` +
  `چک‌لیست (${data.task_type ?? ''}):\n${checklist}\n\nمتن:\n${prev.text ?? ''}`;
return [{ json: { prompt } }];
